"""Settlement — 任务结算系统。

参考 LoopX 的 4 步结算设计：
1. validation — 验证所有子任务已完成且通过审计
2. completion — 汇总所有子任务输出为最终回复
3. writeback — 持久化执行证据到 SQLite
4. quota — 统计 Token 消耗并扣减配额

结算器是任务编排流水线的最后一环，负责：
- 收集所有子任务的执行证据
- 生成人类可读的最终回复
- 持久化任务执行记录
- 更新 Token 配额
"""
import json
import logging
import time
from datetime import datetime

logger = logging.getLogger("agent.orchestration.settlement")


# 最终汇总提示词
_SYNTHESIS_PROMPT = """\
请根据以下子任务的执行结果，为用户的原始请求生成一个完整的回复。

原始请求：{message}

子任务执行结果：
{subtask_results}

要求：
1. 综合所有子任务的输出，给出完整、连贯的回复
2. 如果某些子任务失败，说明哪些部分未能完成
3. 使用中文，简洁专业
"""


class SettlementResult:
    """结算结果。"""

    def __init__(self, success, final_reply, evidence, token_used=0):
        self.success = success
        self.final_reply = final_reply
        self.evidence = evidence
        self.token_used = token_used

    def to_dict(self):
        return {
            'success': self.success,
            'final_reply': self.final_reply,
            'evidence': self.evidence,
            'token_used': self.token_used,
        }


class Settlement:
    """任务结算系统。"""

    def __init__(self, app):
        """
        参数:
            app: AgentApp 实例
        """
        self.app = app

    def settle(self, plan):
        """执行 4 步结算。

        参数:
            plan: TaskPlan 实例（所有子任务已执行完毕）

        返回:
            SettlementResult 实例
        """
        logger.info('开始结算任务计划: %s', plan.plan_id)

        # Step 1: Validation
        validation = self._validate(plan)
        if not validation['ok']:
            logger.warning('结算验证失败: %s', validation['issues'])

        # Step 2: Completion — 汇总最终回复
        final_reply = self._synthesize(plan)

        # Step 3: Writeback — 持久化证据
        evidence = self._collect_evidence(plan)
        self._writeback(plan, evidence)

        # Step 4: Quota — 统计 Token
        token_used = self._count_tokens(plan)

        logger.info('结算完成: plan=%s success=%s tokens=%d',
                    plan.plan_id, validation['ok'], token_used)

        return SettlementResult(
            success=validation['ok'],
            final_reply=final_reply,
            evidence=evidence,
            token_used=token_used)

    def _validate(self, plan):
        """Step 1: 验证所有子任务状态。"""
        issues = []
        done = [t for t in plan.subtasks if t.status == 'done']
        failed = plan.get_failed_subtasks()
        pending = [t for t in plan.subtasks if t.status == 'pending']

        if pending:
            issues.append('%d 个子任务未完成' % len(pending))
        if failed:
            issues.append('%d 个子任务失败: %s' % (
                len(failed), ', '.join(t.id for t in failed)))
        if not done:
            issues.append('没有成功完成的子任务')

        return {
            'ok': len(issues) == 0 or len(done) > len(failed),
            'done': len(done),
            'failed': len(failed),
            'pending': len(pending),
            'issues': issues,
        }

    def _synthesize(self, plan):
        """Step 2: 汇总子任务输出为最终回复。"""
        # 构建子任务结果摘要
        results_text = []
        for t in plan.subtasks:
            status_icon = {
                'done': '✓', 'failed': '✗',
                'skipped': '⊘', 'pending': '○'}.get(t.status, '?')
            results_text.append(
                '[%s] %s: %s' % (
                    status_icon, t.description[:80],
                    str(t.result)[:300] if t.result else '(无输出)'))

        subtask_summary = '\n'.join(results_text)

        # 如果有 LLM，使用 LLM 汇总
        if self.app.llm and self.app.config.llm_configured:
            try:
                return self.app.llm.quick_prompt(
                    system='你是任务汇总专家。请根据子任务结果生成完整回复。',
                    user=_SYNTHESIS_PROMPT.format(
                        message=plan.original_message,
                        subtask_results=subtask_summary),
                    skill='orchestration', category='synthesis')
            except Exception:
                logger.debug('LLM 汇总失败，使用简单拼接', exc_info=True)

        # 兜底：简单拼接
        return self._simple_synthesis(plan, subtask_summary)

    def _simple_synthesis(self, plan, subtask_summary):
        """简单拼接汇总（LLM 不可用时的兜底）。"""
        failed = plan.get_failed_subtasks()
        parts = ['任务执行报告（%s）：\n' % plan.plan_id]
        parts.append(subtask_summary)
        if failed:
            parts.append('\n失败项：%s' % ', '.join(
                t.id for t in failed))
        parts.append('\n原始请求：%s' % plan.original_message[:200])
        return '\n'.join(parts)

    def _collect_evidence(self, plan):
        """Step 3a: 收集执行证据。"""
        evidence = {
            'plan_id': plan.plan_id,
            'timestamp': datetime.now().isoformat(),
            'subtasks': [],
        }
        for t in plan.subtasks:
            evidence['subtasks'].append({
                'id': t.id,
                'description': t.description,
                'status': t.status,
                'result_preview': str(t.result)[:200] if t.result else None,
                'evidence': t.evidence,
            })
        return evidence

    def _writeback(self, plan, evidence):
        """Step 3b: 持久化到 SQLite。"""
        try:
            db = self.app.db
            # 记录主任务
            db.update_task(
                plan.plan_id,
                status='done',
                result=json.dumps(
                    {'subtask_count': len(plan.subtasks)},
                    ensure_ascii=False),
                evidence=json.dumps(evidence, ensure_ascii=False),
                completed_at=datetime.now().isoformat())

            # 记录子任务
            for t in plan.subtasks:
                db.create_task(
                    task_id='%s/%s' % (plan.plan_id, t.id),
                    message=t.description,
                    parent_id=plan.plan_id)
                db.update_task(
                    '%s/%s' % (plan.plan_id, t.id),
                    status=t.status,
                    result=str(t.result)[:2000] if t.result else None,
                    evidence=json.dumps(
                        t.evidence, ensure_ascii=False) if t.evidence else None,
                    token_used=t.token_used)
        except Exception:
            logger.exception('结算持久化失败')

    def _count_tokens(self, plan):
        """Step 4: 统计 Token 消耗。"""
        total = sum(t.token_used for t in plan.subtasks)
        return total
